import { parseDate } from '../lib/site';
import stillOpenData from '../data/still-open.json';

/**
 * Calendar subscription feed for the "Still open" tracker, generated at build
 * time. Every item with a live deadline becomes one all-day VEVENT on its
 * deadline day, so subscribing from Google Calendar, Apple Calendar or any
 * iCal client keeps the entry deadlines on the human's own calendar. The feed
 * is regenerated by every daily build — dropped items vanish, new items
 * appear — so a subscription stays current without any server.
 *
 * Hand-rolled RFC 5545 output: text escaping, 75-octet line folding and
 * UTC-anchored all-day dates are done below, with no new dependencies.
 */

const pad = (value: number) => String(value).padStart(2, '0');

/** `2026-11-02` -> `20261102`, the calendar-date form iCal expects. */
const toCalDate = (date: Date) =>
  `${date.getUTCFullYear()}${pad(date.getUTCMonth() + 1)}${pad(date.getUTCDate())}`;

/** Escapes text property values per RFC 5545 §3.3.11. */
const escapeText = (value: string) =>
  value
    .replaceAll('\\', '\\\\')
    .replaceAll(';', '\\;')
    .replaceAll(',', '\\,')
    .replaceAll('\n', '\\n')
    .replaceAll('\r', '');

/**
 * Folds content lines to 75 octets with the continuation-space convention
 * (RFC 5545 §3.1): the break is a real CRLF followed by a single space, so
 * unfolding is the exact inverse and text and URLs pass through intact.
 */
function fold(line: string): string {
  const bytes = Buffer.from(line, 'utf8');
  if (bytes.length <= 75) return line;
  const chunks: string[] = [];
  let start = 0;
  while (start < bytes.length) {
    // 74 for continuations leaves room for the leading space on the next line.
    const limit = start === 0 ? 75 : 74;
    let end = Math.min(start + limit, bytes.length);
    // Never split a multi-byte character: back off until the end decodes cleanly.
    while (end > start && end < bytes.length && (bytes[end] & 0b11000000) === 0b10000000) end -= 1;
    if (end === start) end = start + 1; // pathological byte, give up on folding it
    chunks.push(bytes.slice(start, end).toString('utf8'));
    start = end;
  }
  return chunks.join('\r\n ');
}

export function GET() {
  const today = new Date().toISOString().slice(0, 10);
  const now = parseDate(today).getTime();
  const stamp = new Date();

  const open = stillOpenData.items
    .filter((item) => /^\d{4}-\d{2}-\d{2}$/.test(item.deadline))
    .filter((item) => parseDate(item.deadline).getTime() >= now)
    .sort((a, b) => a.deadline.localeCompare(b.deadline));

  const lines: string[] = [
    'BEGIN:VCALENDAR',
    'VERSION:2.0',
    'PRODID:-//DailyAgent//Still Open tracker//EN',
    'CALSCALE:GREGORIAN',
    'METHOD:PUBLISH',
    'X-WR-CALNAME:DailyAgent — still open',
    'X-WR-CALDESC:Entry deadlines tracked in the DailyAgent "still open" list.',
  ];

  for (const item of open) {
    const start = parseDate(item.deadline);
    // All-day events end exclusive, so the deadline day occupies one full day.
    const end = new Date(start.getTime() + 86_400_000);
    lines.push(
      'BEGIN:VEVENT',
      `UID:${item.id}@dailyagent`,
      `DTSTAMP:${toCalDate(stamp)}T${pad(stamp.getUTCHours())}${pad(stamp.getUTCMinutes())}${pad(stamp.getUTCSeconds())}Z`,
      `DTSTART;VALUE=DATE:${toCalDate(start)}`,
      `DTEND;VALUE=DATE:${toCalDate(end)}`,
      `SUMMARY:${escapeText(`${item.name} (${item.kind}, deadline)`)}`,
      `DESCRIPTION:${escapeText(item.note ?? 'Entry deadline — see the tracker for details.')}`,
      `URL:${item.url}`,
      'TRANSP:TRANSPARENT',
      'STATUS:CONFIRMED',
      'END:VEVENT',
    );
  }

  lines.push('END:VCALENDAR');

  const body = lines.map(fold).join('\r\n') + '\r\n';

  return new Response(body, {
    headers: {
      'Content-Type': 'text/calendar; charset=utf-8',
      'Content-Disposition': 'inline; filename="still-open.ics"',
    },
  });
}
